list_order_flags.code:
var response = await client.OrderFlags.ListOrderFlagsAsync(
    new Dictionary<string, object?> { ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var orderFlag in ((IReadOnlyList<object?>)body["order_flags"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{orderFlag["id"]} {orderFlag["name"]} {orderFlag["color"]}");

